const body = $input.first()?.json?.body || $input.first()?.json || {};
const plan = body.activityPlan || body.plan || {};
const info = body.basicInfo || body.info || {};
if (!plan.storyContent && !plan.storyTitleEn && !plan.storyTitleZh) throw new Error('Missing activityPlan with story info.');
const pageCount = Math.max(4, Math.min(20, Number(body.pages || body.pageCount || 6)));
return [{ json: {
  userId: String(body.userId || 'anonymous'),
  activityPlan: {
    storyTitleEn: String(plan.storyTitleEn || '').trim(),
    storyTitleZh: String(plan.storyTitleZh || '').trim(),
    storyContent: String(plan.storyContent || '').trim(),
    englishGoal: String(plan.englishGoal || '').trim(),
    wellbeingGoal: String(plan.wellbeingGoal || '').trim(),
    outputGoal: String(plan.outputGoal || '').trim(),
    materials: String(plan.materials || '').trim()
  },
  basicInfo: {
    age: String(info.age || '').trim(),
    level: String(info.level || '').trim(),
    vocabulary: String(info.vocabulary || '').trim(),
    grammar: String(info.grammar || '').trim(),
    themes: Array.isArray(info.themes) ? info.themes : []
  },
  pageCount,
  topic: plan.storyTitleZh || plan.storyTitleEn || info.themes?.[0] || '绘本',
  category: String(body.category || '')
} }];

const request = $('Normalize Request').first().json;
const rag = $input.first().json || {};
const system = '你是专业儿童绘本编辑、儿童英语教育专家和图像分镜导演。只输出严格 JSON，不要 Markdown。';
const user = `请根据活动方案和参考资料，设计绘本的每一页内容。

活动方案:
${JSON.stringify(request.activityPlan, null, 2)}

学生画像:
${JSON.stringify(request.basicInfo, null, 2)}

页数要求: ${request.pageCount} 页（含封面）

参考资料:
${rag.context || '无'}

要求:
1. 第 1 页是封面，最后一页是结尾展示。中间页面推进故事和语言学习。
2. 每页 text 是简短英文句子（适合目标年龄和水平），封面可以同时放英文标题和中文标题。
3. imageDescription 是中文画面描述，详细说明场景、角色表情、构图和色调，适合给画师或 AI 绘图参考。
4. imageDescription 中不要要求在图片里写文字。
5. 如果 basicInfo 提供了 vocabulary 和 grammar，在中间页面中自然融入这些词汇和句型。
6. 参考资料中的儿童心理知识要体现在故事情感设计上。

输出 JSON 形状:
{"pages":[{"page":1,"text":"英文文字","imageDescription":"中文画面描述"}]}`;
return [{ json: { request, rag, messages: [ { role: 'system', content: system }, { role: 'user', content: user } ] } }];

const request = $('Build LLM Prompt').first().json.request;
const rag = $('Build LLM Prompt').first().json.rag;
const response = $input.first().json || {};
let content = response.choices?.[0]?.message?.content || response.output_text || response.text || '';
if (typeof content !== 'string') content = JSON.stringify(content);
content = content.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
let parsed;
try {
  parsed = JSON.parse(content);
} catch (error) {
  const match = content.match(/\{[\s\S]*\}/);
  if (!match) throw new Error('The model did not return parseable JSON.');
  parsed = JSON.parse(match[0]);
}
let rawPages = Array.isArray(parsed.pages) ? parsed.pages : (Array.isArray(parsed) ? parsed : []);
if (!rawPages.length) throw new Error('Model did not return pages array.');
const pages = rawPages.slice(0, request.pageCount).map((page, index) => ({
  id: `page-${Date.now()}-${index + 1}`,
  page: Number(page.page) || index + 1,
  imageDescription: String(page.imageDescription || page.scene || '').trim(),
  text: String(page.text || '').trim(),
  imageUrl: '',
  status: 'placeholder',
  error: ''
}));
if (pages.length !== request.pageCount) {
  return [{ json: {
    success: true,
    pages,
    warning: `Expected ${request.pageCount} pages but got ${pages.length}.`,
    rag: {
      referenceCount: rag.referenceCount || 0,
      references: rag.references || []
    }
  } }];
}
return [{ json: {
  success: true,
  pages,
  rag: {
    referenceCount: rag.referenceCount || 0,
    references: rag.references || []
  }
} }];
